public class InnerContainerGroupDefinitionSupportContainerDefinitionFactory(Action<Humidifier.GameLift.ContainerGroupDefinitionTypes.SupportContainerDefinition> factoryAction = null) : SubResourceFactory<Humidifier.GameLift.ContainerGroupDefinitionTypes.SupportContainerDefinition>
{

    internal InnerContainerGroupDefinitionContainerHealthCheckFactory HealthCheckFactory { get; set; }

    internal InnerContainerGroupDefinitionPortConfigurationFactory PortConfigurationFactory { get; set; }

    protected override Humidifier.GameLift.ContainerGroupDefinitionTypes.SupportContainerDefinition Create()
    {
        var supportContainerDefinitionResult = CreateSupportContainerDefinition();
        factoryAction?.Invoke(supportContainerDefinitionResult);

        return supportContainerDefinitionResult;
    }

    private Humidifier.GameLift.ContainerGroupDefinitionTypes.SupportContainerDefinition CreateSupportContainerDefinition()
    {
        var supportContainerDefinitionResult = new Humidifier.GameLift.ContainerGroupDefinitionTypes.SupportContainerDefinition();

        return supportContainerDefinitionResult;
    }
    public override void CreateChildren(Humidifier.GameLift.ContainerGroupDefinitionTypes.SupportContainerDefinition result)
    {
        base.CreateChildren(result);

        result.HealthCheck ??= HealthCheckFactory?.Build();
        result.PortConfiguration ??= PortConfigurationFactory?.Build();
    }

} // End Of Class

